9.query:
fetch bizevents, from:now()-6h
| filter `event.provider` == "banco.auth"
| summarize sucesso = countIf(status == "success"), falha = countIf(status == "failure"), by:{bin(timestamp, 5m)}

21.query:
fetch bizevents, from:now()-6h
| filter `event.provider` == "banco.fraude"
| summarize total = count(), bloqueadas = countIf(status == "blocked"), by:{bin(timestamp, 5m)}
